Local Rowset &rs0, &rs1, &rs2;
Local Row &row2;
Local number &i, &j, &primaryCount;
Local string &contactType, &contactVal;

&rs0 = GetLevel0();
&rs1 = &rs0(1).GetRowset(Scroll.CSU_JD_BG_HDR);

For &i = 1 To &rs1.ActiveRowCount

   &rs2 = &rs1(&i).GetRowset(Scroll.CSU_JD_BG_CNTCT);
   &primaryCount = 0;

   For &j = 1 To &rs2.ActiveRowCount

      &row2 = &rs2(&j);

      &contactType = &row2.CSU_JD_BG_CNTCT.CSU_JD_CNTCT_TYPE.Value;
      &contactVal = LTrim(RTrim(&row2.CSU_JD_BG_CNTCT.CSU_JD_CONTACT_VAL.Value));

      If &row2.CSU_JD_BG_CNTCT.CSU_JD_PRIMARY.Value = "Y" Then
         &primaryCount = &primaryCount + 1;
            If &primaryCount > 1 Then
        Error ("Only one primary contact is allowed for each header row.");
      End-If;
      End-If;

      If All(&contactType) And None(&contactVal) Then
         Error ("Contact Value is required when Contact Type is entered.");
      End-If;

      If All(&contactVal) And None(&contactType) Then
         Error ("Contact Type is required when Contact Value is entered.");
      End-If;

      If All(&contactVal) Then Evaluate &contactType
         When = "E" /* Email */
            If Find("@", &contactVal) = 0 Then
               Error ("Enter a valid email address.");
            End-If;

         When = "P" /* Phone */
            If Not IsNumber(&contactVal) Then
               Error ("Phone number must be numeric.");
            End-If;

         When = "F" /* Fax */
            If Not IsNumber(&contactVal) Then
               Error ("Fax number must be numeric.");
            End-If;

         When = "X" /* X / Twitter */
            If Find("@", &contactVal) = 0 Then
               Error ("Enter a valid X handle.");
            End-If;
         When-Other
            Warning ("Unknown contact type: " | &contactType);
         End-Evaluate;
      End-If;
   End-For;
End-For;
